const $=s=>document.querySelector(s);let favorites=new Set(),selected=new Set(),onlyFavorites=false,factor=1;try{favorites=new Set(JSON.parse(localStorage.getItem('house-favorites')||'[]'))}catch{}const esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=n=>n==null?'—':Number(n).toLocaleString('pl-PL',{maximumFractionDigits:2});const statusNames={fit:'Obrys sprawdzony',conditional:'Do sprawdzenia / adaptacji',reject:'Odrzucony w tej konfiguracji'};function budget(p){if(!p.area||p.garageArea==null)return null;return [Math.round((p.area*COST.home[0]+(p.costGarageArea??p.garageArea)*COST.garage[0])*factor/10000)*10,Math.round((p.area*COST.home[1]+(p.costGarageArea??p.garageArea)*COST.garage[1])*factor/10000)*10]}function money(p){const b=budget(p);return b?`${num(b[0])}–${num(b[1])} tys. zł`:'Brak danych do oszacowania'}function spec(label,value){return `<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`}function fallback(){return `<svg viewBox="0 0 400 200" aria-label="Brak wizualizacji — schemat bryły" role="img"><path d="M45 155L205 185 360 120 200 94Z" fill="#cbd5c2"/><path d="M95 85L95 145 210 171 210 110Z" fill="#b3bea9"/><path d="M210 110L310 60 310 125 210 171Z" fill="#e9ecdf"/><path d="M95 85L147 25 260 53 210 110Z" fill="#607360"/><path d="M210 110L260 53 310 60Z" fill="#e9ecdf"/><path d="M225 119L295 85 295 121 225 153Z" fill="#819487"/></svg>`}function imageMarkup(p,large=false){return p.image?`<img ${large?'':'loading="lazy"'} src="${esc(p.image)}" alt="Wizualizacja ${esc(p.name)} — ${esc(p.studio)}" referrerpolicy="no-referrer">`:fallback()}function repairImages(){document.querySelectorAll('img').forEach(im=>im.onerror=()=>{im.outerHTML=fallback()})}function render(){let list=PROJECTS.filter(p=>(!onlyFavorites||favorites.has(p.id))&&($('#fit').value==='all'||p.status===$('#fit').value)&&($('#garage').value==='all'||p.garage===+$('#garage').value)&&`${p.name} ${p.studio} ${p.tags||''}`.toLowerCase().includes($('#search').value.toLowerCase().trim()));const sort=$('#sort').value;if(sort==='cost')list.sort((a,b)=>(budget(a)?.[0]??Infinity)-(budget(b)?.[0]??Infinity));if(sort==='area')list.sort((a,b)=>(a.area??Infinity)-(b.area??Infinity));if(sort==='studio')list.sort((a,b)=>a.studio.localeCompare(b.studio,'pl'));$('#resultCount').textContent=`${list.length} z ${PROJECTS.length} projektów${onlyFavorites?' · ulubione':''}`;$('#cards').innerHTML=list.map(p=>`<article class="card"><div class="card-visual">${imageMarkup(p)}<button class="fav" data-fav="${p.id}" aria-label="${favorites.has(p.id)?'Usuń z':'Dodaj do'} ulubionych: ${esc(p.name)}" aria-pressed="${favorites.has(p.id)}">${favorites.has(p.id)?'♥':'♡'}</button></div><div class="card-body"><span class="status ${p.status}">${statusNames[p.status]}</span><p class="studio">${esc(p.studio)}</p><h3>${esc(p.name)}</h3><dl class="specs">${spec('Część domowa (do budżetu)',num(p.area)+' m²')}${spec('Bryła budynku',p.width&&p.depth?`${num(p.width)} × ${num(p.depth)} m`:'Niepotwierdzona')}${spec('Garaż',p.garage?`${p.garage} stan. · ${num(p.garageArea)} m²`:'Brak / nieustalone')}${spec('Program',p.program)}</dl><p class="verdict">${esc(p.verdict)}</p><div class="money"><strong>${money(p)}</strong><span>szacunek brutto · stan deweloperski · bez trudnego gruntu</span></div><div class="actions"><button class="detail-btn" data-detail="${p.id}">Szczegóły ↗</button><label class="check"><input type="checkbox" data-compare="${p.id}" ${selected.has(p.id)?'checked':''}>Porównaj</label></div></div></article>`).join('');$('#empty').hidden=!!list.length;$('#favCount').textContent=favorites.size;$('#favFilter').setAttribute('aria-pressed',onlyFavorites);repairImages();updateBar()}
function updateBar(){$('#compareBar').hidden=!selected.size;$('#compareCount').textContent=`Wybrano ${selected.size} / 4 projekty`;}function resetFilters(){for(const id of ['fit','garage'])$('#'+id).value='all';$('#sort').value='recommended';$('#search').value='';onlyFavorites=false;render()}function listItems(items){return `<ul>${(items||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`}function showDetail(id){const p=PROJECTS.find(p=>p.id===id);if(!p)return;$('#detailContent').innerHTML=`<p class="studio">${esc(p.studio)}</p><h2>${esc(p.name)}</h2><span class="status ${p.status}">${statusNames[p.status]}</span><div class="detail-top"><div>${imageMarkup(p,true)}<p class="small">Wizualizacja pracowni; otwórz źródło, aby obejrzeć kompletny projekt.</p></div><div><p class="lead">${esc(p.verdict)}</p><div class="money"><strong>${money(p)}</strong><span>Wspólny model budżetu brutto, nie kosztorys tego projektu</span></div><a class="source-link" href="${esc(p.url)}" target="_blank" rel="noopener">Projekt u autora ↗</a>${p.floor?` <a href="${esc(p.floor)}" target="_blank" rel="noopener">Rzut parteru ↗</a>`:''}</div></div><dl class="specs">${spec('Część domowa (do budżetu)',`${num(p.area)} m²`)}${spec('Garaż',`${num(p.garageArea)} m² / ${p.garage} stan.`)}${spec('Pow. zabudowy',`${num(p.footprint)} m²`)}${spec('Wymiary zewnętrzne',p.width&&p.depth?`${num(p.width)} × ${num(p.depth)} m`:'Do potwierdzenia')}${spec('Dach',p.roof)}${spec('Program',p.program)}</dl><p class="small">Zakres powierzchni: ${esc(p.areaNote)}. ${esc(p.dimensionNote||'Wymiary katalogowe / odczyt rzutu wskazany w źródle.')}</p><div class="detail-grid"><div><h3>Co przemawia za</h3>${listItems(p.pros)}</div><div><h3>Kompromisy</h3>${listItems(p.cons)}</div><div><h3>Ustawienie na działce</h3><p>${esc(p.orientation)}</p><p class="small">${esc(p.fitEvidence.replace(/(?:przy lokalnym |przy |: przykładowo )x=[0-9,]+; y=[0-9,]+;?/g,''))}</p></div><div><h3>Adaptacja i konstrukcja</h3><p>${esc(p.adaptation)}</p><p class="small">${esc(p.structure||'Rozwiązania konstrukcyjne wymagają potwierdzenia u autora.')}</p></div></div><div class="note">Ocena wstępna. Obrys, zgodność MPZP i funkcjonalny wjazd to odrębne warunki. Zmiana technologii ścian, fundamentów, stropu, kąta dachu lub konstrukcji garażu wymaga projektu adaptacji. Nie jest automatycznie drobną zmianą.</div><p class="small">Dane źródłowe sprawdzone 17.10.2026. Braki są oznaczone; ceny i projekty mogą się zmieniać.</p>`;repairImages();$('#detail').showModal()}function showComparison(){const ps=PROJECTS.filter(p=>selected.has(p.id));const rows=[['Dopasowanie',p=>statusNames[p.status]],['Budżet brutto',money],['Powierzchnia do modelu',p=>num(p.area)+' m²'],['Zakres powierzchni',p=>p.areaNote],['Wymiary bryły',p=>p.width&&p.depth?`${num(p.width)} × ${num(p.depth)} m`:'Niepotwierdzone'],['Pow. zabudowy',p=>num(p.footprint)+' m²'],['Garaż',p=>`${p.garage} stan. / ${num(p.garageArea)} m²`],['Program',p=>p.program],['Dach',p=>p.roof],['Najważniejszy kompromis',p=>p.cons[0]],['Ustawienie',p=>p.orientation]];$('#comparisonContent').innerHTML=`<table><thead><tr><th>Parametr</th>${ps.map(p=>`<th>${esc(p.name)}<p class="small">${esc(p.studio)}</p><a href="${esc(p.url)}" target="_blank" rel="noopener">Źródło ↗</a></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><td>${label}</td>${ps.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}</tbody></table>`;$('#comparison').showModal()}
$('#cards').addEventListener('click',e=>{const fav=e.target.closest('[data-fav]'),detail=e.target.closest('[data-detail]');if(fav){const id=fav.dataset.fav;favorites.has(id)?favorites.delete(id):favorites.add(id);try{localStorage.setItem('house-favorites',JSON.stringify([...favorites]))}catch{}render()}if(detail)showDetail(detail.dataset.detail)});$('#cards').addEventListener('change',e=>{const id=e.target.dataset.compare;if(!id)return;if(e.target.checked){if(selected.size>=4){e.target.checked=false;alert('Porównaj maksymalnie 4 projekty jednocześnie. Usuń jeden z zaznaczonych.');return}selected.add(id)}else selected.delete(id);updateBar()});for(const id of ['fit','garage','sort'])$('#'+id).addEventListener('change',render);$('#search').addEventListener('input',render);$('#reset').onclick=resetFilters;$('#favFilter').onclick=()=>{onlyFavorites=!onlyFavorites;render();$('#projekty').scrollIntoView()};$('#compareOpen').onclick=showComparison;$('#compareClear').onclick=()=>{selected.clear();render()};document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));document.querySelectorAll('[data-pick]').forEach(a=>a.onclick=e=>{e.preventDefault();showDetail(a.dataset.pick)});$('#factor').oninput=e=>{factor=e.target.value/100;$('#factorValue').textContent=e.target.value+'%';render()};$('#totalCount').textContent=PROJECTS.length;$('#studioCount').textContent=new Set(PROJECTS.map(p=>p.studio)).size;$('#costMethod').textContent=COST.description;$('#costSources').innerHTML=COST.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)} ↗</a></p>`).join('');render();
